<script>
    import gsap from 'gsap';
    import {
        onMounted,
        nextTick,
        ref,
        onUnmounted
    } from 'vue';

    export default {
        name: 'UnauthWidget',
        setup() {
            var unauthTl = gsap.timeline();
            onMounted(async () => {
                await nextTick(); // Ensures Vue has finished rendering before GSAP runs

                var midOutlineContent = document.querySelectorAll('.unauthwidget svg path:not(.outline):not(.error-dash)')
                var errorDashes = document.querySelectorAll('.unauthwidget svg path.error-dash')

                unauthTl.set("#maskRect", {
                    width: "0%",
                });
                unauthTl.set("#maskRectRev", {
                    width: "0%",
                });
                unauthTl.set(midOutlineContent, {
                    opacity: 0,
                });
                unauthTl.to("#maskRect", { 
                    width: "100%", 
                    duration: 1, 
                    ease: "linear",
                    delay: 0.5,
                });
                unauthTl.to(midOutlineContent, {
                    opacity: 1,
                    duration: 0.3,
                    ease: "power1.inOut",
                    onComplete: () => {
                        unauthTl.to("#maskRectRev", { 
                            width: "100%", 
                            duration: 1, 
                            ease: "linear",
                            delay: 0.5,
                        });
                    }
                })
                
            });
            onUnmounted(async () => {
               
            });

            return {};
        },
    };
</script>

